#include <iostream>
#include <cstdio>
using namespace std;
typedef long long ll;
const int MOD=1000000007;

struct Matrix {
    int mat[33][33];
} identityMatrix, matrices[70], finalResult, prefixMatrices[70], suffixMatrices[70];

ll totalN, totalK;

void printMatrix(const Matrix &m){
    for(int i=0; i<=totalK; i++){
        for(int j=0; j<=totalK; j++)
            cout << m.mat[i][j] << ' ';
        cout << endl;
    }
    cout << endl;
}

Matrix matrixMultiply(const Matrix &a, const Matrix &b){
    Matrix c=identityMatrix;
    for(int k=0; k<=totalK; k++){
        for(int i=0; i<=totalK; i++){
            for(int j=0; j<=totalK; j++){
                ll val = ((ll)a.mat[i][k] * b.mat[k][j]) % MOD;
                c.mat[i][j] = (c.mat[i][j] + val) % MOD;
            }
        }
    }
    return c;
}

void preparePrefixSuffix(){
    int i;
    prefixMatrices[0] = matrices[0];
    for(i=1; i<totalK; i++)
        prefixMatrices[i] = matrixMultiply(prefixMatrices[i-1], matrices[i]);
    suffixMatrices[totalK-1] = matrices[totalK-1];
    for(i=totalK-2; i>=0; i--)
        suffixMatrices[i] = matrixMultiply(matrices[i], suffixMatrices[i+1]);
    matrices[0] = suffixMatrices[0];
    for(i=1; i<totalK; i++)
        matrices[i] = matrixMultiply(suffixMatrices[i], prefixMatrices[i-1]);
}

void execute(){
    cin >> totalN >> totalK;
    int i, j;
    finalResult = identityMatrix;
    for(i=0; i<totalK; i++){
        matrices[i] = identityMatrix;
        for(j=0; j<=totalK; j++)
            matrices[i].mat[j][j] = 1;
        for(j=0; j<=totalK; j++)
            matrices[i].mat[j][i] = 1;
        finalResult.mat[i][i] = 1;
    }
    finalResult.mat[totalK][totalK] = 1;
    while(totalN > 0){
        int rem = totalN % totalK;
        if(rem != 0){
            ll pos=0, tmp=totalN;
            while(tmp){
                tmp /= totalK;
                pos = (pos + tmp) % totalK;
            }
            for(i=rem-1; i>=0; i--){
                finalResult = matrixMultiply(matrices[(pos + i) % totalK], finalResult);
            }
        }
        preparePrefixSuffix();
        totalN /= totalK;
    }
    int res=1;
    for(i=0; i<totalK; i++)
        res = (res + finalResult.mat[totalK][i]) % MOD;
    cout << res << endl;
}

int main(){
    execute();
    return 0;
}
